8	/**
9	 * 사이트 배치를 담당하는 순수 로직 (docs/plan/data/module.md · docs/systems/map.md).
10	 * 컨테이너와 수학 연산 외에는 엔진에 손대지 않으므로, 같은 시드는 모든 머신에서 같은
11	 * 배치를 만들어낸다 — 호스트는 시드 하나만 복제하고 각 클라이언트가 이걸 로컬에서
12	 * 실행한다. ACL9SiteMap이 그 결과를 액터로 바꾼다.
13	 *
14	 * **사이트 전체가 모듈 격자다** — 축사 안쪽만이 아니라 마당까지 전부. 모듈은 프리팹이
15	 * 아니라 표(UCL9ModuleDef)의 행이고, 이 코드가 하는 일은 "어느 칸에 어느 모듈이
16	 * 어느 방향으로 앉는가"와 "어느 칸 경계가 벽이고 어느 쪽이 문인가"를 정하는 것까지다.
17	 * 그 발자국을 어떤 메시로 채울지는 조각 표(UCL9PieceDef)가 정한다.
18	 *
19	 * 좌표는 사이트 로컬 센티미터 단위다: (0,0)이 트럭 패드이고, +X가 격자 안쪽(동쪽)을
20	 * 향하며 +Y는 북쪽이다. **층이 없다** — 높이차는 모듈 안의 계단으로 내고 이웃으로
21	 * 전파되지 않는다 (module.md 결정 2).
22	 */
23	
24	/** 격자 변 하나의 상태. 변은 칸 경계이며, 모듈 안쪽 경계는 Open이다 */
25	enum class ECL9GridEdge : uint8
26	{
27		/** 뚫려 있다 — 같은 모듈 안이거나 격자 바깥이다 */
28		Open,
29		/** 막혔다 — 모듈 외곽이거나, 이웃이 있어도 소켓이 안 맞은 자리다 */
30		Wall,
31		/** 두 모듈을 잇는 문 */
32		Door,
33		/** 일방향 비상구 (flapIn). 한 판에 하나뿐이다 */
34		Flap
35	};
36	
37	/** 사이트 행에서 복사해온 배치 설정값들 (docs/plan/data/module.md) */
38	struct FCL9SiteParams
39	{
40		/** 모듈 표와 조각 표를 함께 가리키는 이름 (UCL9SiteDef::Theme) */
41		FName Theme;
42	
43		/** 격자 칸 하나의 크기 (cm) */
44		float CellSize = 500.f;
45	
46		/** 이 판에 놓을 모듈 수 — 사이트 기준값 × 일자 커브를 이미 반영한 값이다 */
47		int32 ModuleCount = 24;
48	
49		/** 트럭 패드에서 시작 모듈 바깥면까지 (cm) */
50		float EntryOffset = 1000.f;
51	
52		/**
53		 * 벽 두께. 표 컬럼이 아니라 ACL9SiteMap이 `barn` 종류가 쓰는 조각의 실측 두께로
54		 * 채워 준다 (docs/systems/asset-swap.md) — 여기 적힌 값은 조각을 아직 못 읽었을
55		 * 때의 폴백이다.
56		 */
57		float WallThickness = 30.f;
58	
59		/**
60		 * 문 하나의 폭 (cm). 이것도 표가 아니라 `door` 종류가 쓰는 조각의 실측 폭에서
61		 * 온다 — 팩을 갈아 끼우면 문 크기가 그 팩 문짝을 따라간다.
62		 */
63		float DoorWidth = 250.f;
64	
65		/** 세울 수 있는 최대 층수 (UCL9SiteDef::MaxFloors). 1이면 단층이다 */
66		int32 MaxFloors = 1;
67	
68		/** 층 사이마다 놓을 계단 모듈 수의 범위 — 시드가 이 안에서 뽑는다 */
69		int32 StairCountMin = 2;
70		int32 StairCountMax = 4;
71	
72		/** 위층 하나가 받는 모듈 예산 = 아래층 예산 × 이 값 (UCL9SiteDef::UpperFloorShare) */
73		float UpperFloorShare = 0.5f;
74	
75		/** 실내 모듈에 천장을 씌우나 (UCL9SiteDef::bBuildCeilings) */
76		bool bBuildCeilings = true;
77	
78		/** 빛 값이 있는 소품 가운데 실제로 켜지는 비율 (UCL9SiteDef::LampDensity) — 배치기가 시드로 고른다 */
79		float LampDensity = 1.f;
80	
81		/**
82		 * 이미 놓인 모듈끼리 맞닿았을 때 문을 뚫을 확률 (UCL9SiteDef::LoopChance) — 여기서
83		 * 고리(우회로)가 생긴다 (DunGen의 `DoorwayConnectionChance`). 0이면 순수한 나무 구조다.
84		 */
85		float LoopChance = 0.25f;
86	
87		/** 전체 모듈 중 본줄기가 차지하는 비율 (UCL9SiteDef::MainPathShare) — 나머지는 곁가지다 */
88		float MainPathShare = 0.4f;
89	
90		/**
91		 * 곁가지 예산 중 통로(Passage)·막다른 방(DeadEnd)의 비율 (UCL9SiteDef::PassageShare ·
92		 * DeadEndShare) — 둘을 뺀 나머지가 방(Normal)이다.
93		 */
94		float PassageShare = 0.28f;
95		float DeadEndShare = 0.32f;
96	
97		/** Special 행 하나를 몇 번 놓나 (UCL9SiteDef::SpecialCopies) — 큰 판에 납품 방(항아리)이 하나뿐이면 반납 길이 너무 멀다 */
98		int32 SpecialCopies = 1;
99	
100		/**
101		 * 한 층의 높이 (cm) — 아래층 바닥에서 위층 바닥까지다. 모듈 천장 높이에
102		 * 천장 판과 바닥 판의 두께를 더한 값이고, 표가 아니라 ACL9SiteMap이 조각
103		 * 실측으로 채워 준다 (docs/systems/asset-swap.md).
104		 */
105		float FloorHeight = 460.f;
106	};
107	
108	/** 격자에 앉은 모듈 하나 */
109	struct FCL9ModulePlacement
110	{
111		/** 이 자리에 앉은 표의 행 */
112		const UCL9ModuleDef* Def = nullptr;
113	
114		/** 차지한 칸 사각형의 최소 모서리 */
115		FIntPoint Origin = FIntPoint::ZeroValue;
116	
117		/** 회전을 적용한 뒤의 칸 크기 */
118		FIntPoint Size = FIntPoint(1, 1);
119	
120		/** 반시계 90° 단위 회전 (0~3) */
121		int32 Rotation = 0;
122	
123		/** 회전을 적용한 뒤 열려 있는 변 (ECL9ModuleSide 비트) */
124		uint8 Sockets = 0;
125	
126		/** 시작 모듈에서 몇 개의 모듈을 거쳐 왔나 — 멀수록 깊은 곳이다 */
127		int32 Hops = 0;
128	
129		/** 이 모듈이 앉은 층. 0이 1층이다 */
130		int32 Floor = 0;
131	
132		/**
133		 * 위층으로 올라가는 계단 모듈인가. 그렇다면 이 모듈은 `Floor`와 `Floor + 1`의
134		 * **같은 칸을 함께 차지한다** — 두 층에서 같은 인덱스가 나오므로 도달 검사가
135		 * 층을 자연스럽게 넘나든다.
136		 */
137		bool bStairUp = false;
138	
139		/** 이 모듈이 차지한 가장 높은 층 */
140		int32 TopFloor() const
141		{
142			return Floor + (bStairUp ? 1 : 0);
143		}
144	};
145	
146	/**
147	 * 스폰·순찰이 쓰는 지점 하나 (module.md 결정 4, REPO의 `LevelPoint`에 해당).
148	 * 지금은 배치된 칸에서 파생해 만들지만, 나중에 소품 세트가 "이 선반 위" 같은 자기
149	 * 지점을 밀어 넣는 자리도 여기다 — 그래서 칸이 아니라 별도 목록으로 둔다.
150	 */
151	struct FCL9LevelPoint
152	{
153		/** 사이트 로컬 cm */
154		FVector2D Local = FVector2D::ZeroVector;
155	
156		/** ECL9PointPurpose 비트마스크 */
157		uint8 Purposes = 0;
158	
159		/** 이 지점이 속한 모듈 */
160		int32 Module = INDEX_NONE;
161	
162		/** 시작 모듈로부터의 홉 수 — 그 모듈의 값을 복사해 둔 것이다 */
163		int32 Hops = 0;
164	
165		/** 이 지점이 있는 층 — 사이트 로컬 Z는 이 값 × FCL9SiteParams::FloorHeight다 */
166		int32 Floor = 0;
167	
168		bool Has(ECL9PointPurpose Purpose) const
169		{
170			return (Purposes & static_cast<uint8>(Purpose)) != 0;
171		}
172	};
173	
174	struct FCL9SiteLayout
175	{
176		uint32 Seed = 0;
177	
178		/** 시드 0이거나 쓸 모듈이 없으면 false — 그 경우 아무것도 짓지 않는다 */
179		bool bBuilt = false;
180	
181		/**
182		 * 이 판이 놓으려 한 모듈 수 — 1층 ModuleCount에 위층 몫(절반씩)을 더한 값이다.
183		 * 실제 Modules.Num()이 이보다 눈에 띄게 적으면 격자가 좁거나 소켓이 안 맞는 것이다.
184		 */
185		int32 Wanted = 0;
186	
187		/** 격자 칸 수 — 층이 몇이든 평면 크기는 하나다 */
188		FIntPoint GridSize = FIntPoint::ZeroValue;
189	
190		/**
191		 * 실제로 선 층 수 (1 이상). `FCL9SiteParams::MaxFloors`가 상한이고, 위층은
192		 * 아래층이 받쳐 주는 자리에만 설 수 있어서 자리가 없으면 그보다 낮게 끝난다.
193		 */
194		int32 FloorCount = 1;
195	
196		/** 칸 (0,0)의 최소 모서리가 놓이는 사이트 로컬 좌표 */
197		FVector2D Origin = FVector2D::ZeroVector;
198	
199		/** FloorCount * GridSize.X * GridSize.Y — 그 칸을 차지한 모듈 인덱스, 빈 칸은 INDEX_NONE */
200		TArray<int32> CellModule;
201	
202		/** FloorCount * (GridSize.X+1) * GridSize.Y — 칸 (gx-1,gy)와 (gx,gy) 사이의 세로 변 */
203		TArray<uint8> EdgeX;
204	
205		/** FloorCount * GridSize.X * (GridSize.Y+1) — 칸 (gx,gy-1)와 (gx,gy) 사이의 가로 변 */
206		TArray<uint8> EdgeY;
207	
208		TArray<FCL9ModulePlacement> Modules;
209	
210		TArray<FCL9LevelPoint> Points;
211	
212		/** 트럭이 붙는 칸 — 시작 모듈의 서쪽 끝이다 */
213		FIntPoint EntryCell = FIntPoint::ZeroValue;
214	
215		bool IsInside(FIntPoint Cell) const
216		{
217			return Cell.X >= 0 && Cell.Y >= 0 && Cell.X < GridSize.X && Cell.Y < GridSize.Y;
218		}
219	
220		bool IsFloor(int32 Floor) const
221		{
222			return Floor >= 0 && Floor < FloorCount;
223		}
224	
225		/** 한 층이 쓰는 칸 배열의 길이 — 층 인덱스에 곱하면 그 층의 시작이다 */
226		int32 CellStride() const { return GridSize.X * GridSize.Y; }
227		int32 EdgeXStride() const { return (GridSize.X + 1) * GridSize.Y; }
228		int32 EdgeYStride() const { return GridSize.X * (GridSize.Y + 1); }
229	
230		int32 CellAt(int32 Floor, FIntPoint Cell) const
231		{
232			return IsInside(Cell) && IsFloor(Floor)
233				? CellModule[Floor * CellStride() + Cell.X + Cell.Y * GridSize.X]
234				: INDEX_NONE;
235		}
236	
237		/** 칸 (gx-1,gy)와 (gx,gy) 사이의 세로 변 — gx는 0 ~ GridSize.X */
238		ECL9GridEdge EdgeAtX(int32 Floor, int32 GX, int32 GY) const
239		{
240			return static_cast<ECL9GridEdge>(EdgeX[Floor * EdgeXStride() + GX + GY * (GridSize.X + 1)]);
241		}
242	
243		/** 칸 (gx,gy-1)와 (gx,gy) 사이의 가로 변 — gy는 0 ~ GridSize.Y */
244		ECL9GridEdge EdgeAtY(int32 Floor, int32 GX, int32 GY) const
245		{
246			return static_cast<ECL9GridEdge>(EdgeY[Floor * EdgeYStride() + GX + GY * GridSize.X]);
247		}
248	};
249	
250	/** 배치할 박스 하나 — kind 이름이 seg kind 테이블을 인덱싱한다(docs/plan/data/segkind.md) */
251	struct FCL9SiteSeg
252	{
253		FName Kind;
254	
255		/** 사이트 로컬 cm 단위의 바닥 면적 */
256		FBox2D Rect;
257	
258		/**
259		 * 이 박스가 기준으로 삼는 Z. 벽은 여기서 위로, 바닥은 여기서 아래로, 천장은
260		 * 여기서 위로 자란다 — 어느 쪽인지는 seg kind가 정한다.
261		 *
262		 * 층이 생긴 뒤로는 그 모듈이 앉은 층이 여기에 실린다 —
263		 * `Floor × FCL9SiteParams::FloorHeight`다. 계단의 디딤판도 이 값만 다른 바닥 박스다.
264		 */
265		float BaseZ = 0.f;
266	
267		/**
268		 * 이 박스가 바깥으로 보는 방향, 사이트 로컬 XY 단위벡터. 방향이 뜻을 갖는 종류만
269		 * 채운다 — 지금은 비상구뿐이고, 여닫이문이 어느 쪽으로만 열릴지를 이걸로 정한다.
270		 */
271		FVector2D Outward = FVector2D::ZeroVector;
272	};
273	
274	namespace CL9SegKind
275	{
276		inline const FName& Wall() { static const FName Name(TEXT("wall")); return Name; }
277		inline const FName& Barn() { static const FName Name(TEXT("barn")); return Name; }
278		inline const FName& Door() { static const FName Name(TEXT("door")); return Name; }
279		inline const FName& FlapIn() { static const FName Name(TEXT("flapIn")); return Name; }
280		inline const FName& Floor() { static const FName Name(TEXT("floor")); return Name; }
281		inline const FName& Ceiling() { static const FName Name(TEXT("ceiling")); return Name; }
282		/** 야외 모듈의 바닥 — 실내 바닥과 조각이 다르다(흙·자갈). 바닥처럼 기준점 아래로 자란다 */
283		inline const FName& Yard() { static const FName Name(TEXT("yard")); return Name; }
284		/** 계단 디딤판 — 바닥 종류지만 조각이 다르다(미끄럼 방지 판). 기준점 아래로 자란다 */
285		inline const FName& Tread() { static const FName Name(TEXT("tread")); return Name; }
286		/** 문·비상구 양옆에 남는 짧은 벽 토막 — 온전한 벽 조각을 눌러 넣지 않도록 종류를 나눈다 */
287		inline const FName& BarnStub() { static const FName Name(TEXT("barnStub")); return Name; }
288		inline const FName& WallStub() { static const FName Name(TEXT("wallStub")); return Name; }
289	
290		/** 기준점에서 아래로 자라는 종류들 — 바닥·마당·디딤판. 나머지는 위로 자란다 */
291		inline bool GrowsDown(const FName& Kind)
292		{
293			return Kind == Floor() || Kind == Yard() || Kind == Tread();
294		}
295	}
296	
297	namespace CL9SiteLayout
298	{
299		/**
300		 * **계단을 올라가면 반드시 이어지는 공간이 있어야 한다** (2026-09-10 사용자 규칙: "계단이
301		 * 있는 방은 계단 이후 바로 고립되면 안 된다"). 계단 하나가 위층에 최소 이만큼의 모듈을
302		 * 자기 둘레에 틔우지 못하면 그 계단은 계단이 아니게 되돌린다 — 개수를 줄여서 맞추는 게
303		 * 아니라, 갈 데 없는 계단이 애초에 서지 않게 한다.
304		 */
305		constexpr int32 StairMinReach = 3;
306	
307		/**
308		 * 모듈을 조립해 한 판을 만든다. 시드가 0이거나 쓸 모듈이 없으면 아무것도 짓지
309		 * 않은 배치를 돌려준다(bBuilt == false). Modules는 레지스트리 순서 그대로여야
310		 * 한다 — 순서가 곧 결정성의 일부다.
311		 */
312		FCL9SiteLayout Generate(const FCL9SiteParams& Params, const TArray<const UCL9ModuleDef*>& Modules, uint32 Seed);
313	
314		/** 맵 액터가 배치할 모든 박스 — 바닥, 천장, 벽, 문틀, 비상구 */
315		void BuildSegments(const FCL9SiteParams& Params, const FCL9SiteLayout& Layout, TArray<FCL9SiteSeg>& OutSegs);
316	
317		/** 칸 하나의 중심, 사이트 로컬 좌표 */
318		FVector2D CellCenter(const FCL9SiteParams& Params, const FCL9SiteLayout& Layout, FIntPoint Cell);
319	
320		/**
321		 * 회전 전 모듈 로컬 좌표(cm, 원점 = 회전 전 사각형의 최소 모서리)를 사이트 로컬 좌표로
322		 * 옮긴다. 회전은 `RotateSockets`와 같은 뜻이다 — 반시계 90° × r, 회전 전의 East가 회전
323		 * 후의 North가 된다. 소품 세트가 이 변환으로 모듈을 따라 돈다.
324		 */
325		FVector2D ModuleLocalToSite(const FCL9SiteParams& Params, const FCL9SiteLayout& Layout, const FCL9ModulePlacement& Module, FVector2D Local);
326	
327		/** 회전 전 변 번호(N=0·E=1·S=2·W=3)가 회전 r 뒤에 향하는 변 — `RotateSockets`의 비트 이동과 같다 */
328		int32 RotateSide(int32 Side, int32 Rotation);
329	
330		/** 칸의 그 변(N=0·E=1·S=2·W=3) 상태 */
331		ECL9GridEdge EdgeOfCell(const FCL9SiteLayout& Layout, int32 Floor, FIntPoint Cell, int32 Side);
332	
333		/**
334		 * 그 용도로 쓸 수 있는 지점들의 인덱스를, **시작 모듈에서 먼 것부터** 담는다
335		 * (module.md 결정 4). 몬스터는 앞쪽에서, 재료는 전체에서 고르면 "깊이 들어갈수록
336		 * 위험하다"가 배치만으로 성립한다.
337		 */
338		void PointsOfPurpose(const FCL9SiteLayout& Layout, ECL9PointPurpose Purpose, TArray<int32>& OutIndices);
