888				Cand.Def = Def;
889				Cand.Origin = FIntPoint(0, (Span - Size.Y) / 2);
890				Cand.Size = Size;
891				Cand.Rotation = Rotation;
892				Cand.Sockets = Sockets;
893				if (Fits(Layout, 0, Cand.Origin, Cand.Size) && !StartCandidates.ContainsByPredicate([&Cand](const FCandidate& Other) { return Cand.SameOutcome(Other); }))
894				{
895					StartCandidates.Add(Cand);
896				}
897			}
898		}
899		const FCandidate* StartPick = PickCandidate(StartCandidates, Rng);
900		if (StartPick == nullptr)
901		{
902			return Layout;
903		}
904	
905		const int32 StartIndex = Occupy(Layout, *StartPick, 0, /*Floor*/ 0, /*bStairUp*/ false);
906		Layout.EntryCell = FIntPoint(StartPick->Origin.X, StartPick->Origin.Y + StartPick->Size.Y / 2);
907		// 입구 문은 격자 바깥으로 난다 — 트럭은 밖에 있고 걸어 들어온다 (module.md 결정 6)
908		SetEdge(Layout, 0, Layout.EntryCell, SideW, ECL9GridEdge::Door);
909	
910		TArray<TArray<FFrontier>> Frontiers;
911		Frontiers.SetNum(Layout.FloorCount);
912		OpenNeighbours(Layout, 0, StartIndex, Frontiers[0], Params.LoopChance, Rng);
913	
914		// ---- 층별 예산. **1층은 ModuleCount를 그대로 받고, 위층은 그 UpperFloorShare 배씩 덧붙는다**
915		//      (2026-09-10 사용자 결정 "절반씩" → 2026-09-16 사이트 컬럼으로). 층을 켠다고 1층이 좁아지지
916		//      않는다 — 2층을 켜는 게 곧 맵이 커지는 일이다. 위층은 아래층이 받쳐 주는 자리에만 설 수
917		//      있어서 예산을 다 쓰지는 못한다. 계단이 위층을 틔울 때 위층 예산을 먼저 당겨 쓰므로 배열이어야 한다.
918		TArray<int32> FloorBudget;
919		Layout.Wanted = 1;
920		for (int32 Floor = 0; Floor < Layout.FloorCount; ++Floor)
921		{
922			const int32 Budget = Floor == 0
923				? Params.ModuleCount - 1
924				: FMath::Max(0, FMath::RoundToInt(Params.ModuleCount * FMath::Pow(Params.UpperFloorShare, static_cast<float>(Floor))));
925			FloorBudget.Add(Budget);
926			Layout.Wanted += Budget;
927		}
928	
929		for (int32 Floor = 0; Floor < Layout.FloorCount; ++Floor)
930		{
931			const bool bTop = Floor == Layout.FloorCount - 1;
932	
933			// 위층이 있으면 계단을 그만큼 섞어 놓는다. 시드가 뽑으므로 판마다 다르다.
934			const int32 StairWant = bTop
935				? 0
936				: FMath::Max(1, Rng.RandRange(FMath::Max(1, Params.StairCountMin), FMath::Max(1, Params.StairCountMax)));
937	
938			GrowFloor(Layout, Params, Floor, FloorBudget[Floor], StairWant, Pools, Frontiers, /*bLeadPhases*/ Floor == 0, Rng);
939	
940			if (bTop)
941			{
942				break;
943			}
944	
945			// **계단마다 위층을 먼저 틔운다.** 자기 둘레에 방을 못 붙이는 계단은 되돌리므로,
946			// 살아남은 계단은 올라가면 반드시 갈 데가 있다. 하나도 못 살아남으면 위층은 없다.
947			if (SecureStairs(Layout, Params, Floor, FloorBudget[Floor + 1], Pools, Frontiers, Rng) == 0)
948			{
949				Layout.FloorCount = Floor + 1;
950				break;
951			}
952		}
953	
954		// 층이 줄었으면 그 위로 뻗던 계단은 더 이상 계단이 아니다 — 그냥 방으로 남긴다.
955		for (FCL9ModulePlacement& Module : Layout.Modules)
956		{
957			if (Module.bStairUp && Module.Floor + 1 >= Layout.FloorCount)
958			{
959				Module.bStairUp = false;
960			}
961		}
962	
963		// 층이 줄었으면 남는 층의 칸·변 배열을 잘라 낸다 — 해시와 순회가 실제 층만 보도록.
964		Layout.CellModule.SetNum(Layout.FloorCount * Layout.CellStride());
965		Layout.EdgeX.SetNum(Layout.FloorCount * Layout.EdgeXStride());
966		Layout.EdgeY.SetNum(Layout.FloorCount * Layout.EdgeYStride());
967	
968		SealEdges(Layout);
969		CarveEmergencyExit(Layout);
970		BuildPoints(Params, Layout);
971		Layout.bBuilt = true;
972		return Layout;
973	}
