82		 * 주는가. `bAlsoUpper`면 바로 위층의 같은 칸까지 비어 있어야 한다 — 계단 모듈이
83		 * 두 층을 함께 차지하기 때문이다.
84		 */
85		bool Fits(const FCL9SiteLayout& Layout, int32 Floor, FIntPoint Origin, FIntPoint Size, bool bAlsoUpper = false)
86		{
87			if (Origin.X < 0 || Origin.Y < 0 || Origin.X + Size.X > Layout.GridSize.X || Origin.Y + Size.Y > Layout.GridSize.Y)
88			{
89				return false;
90			}
91			if (!Layout.IsFloor(Floor) || (bAlsoUpper && !Layout.IsFloor(Floor + 1)))
92			{
93				return false;
94			}
95			for (int32 Y = 0; Y < Size.Y; ++Y)
96			{
97				for (int32 X = 0; X < Size.X; ++X)
98				{
99					const FIntPoint Cell(Origin.X + X, Origin.Y + Y);
100					if (Layout.CellAt(Floor, Cell) != INDEX_NONE)
101					{
102						return false;
103					}
104					if (bAlsoUpper && Layout.CellAt(Floor + 1, Cell) != INDEX_NONE)
105					{
106						return false;
107					}
108					// 위층은 허공에 뜰 수 없다 — 아래층 실내 모듈이 받쳐 주는 자리에만 선다.
109					if (Floor > 0 && !CanCarry(Layout, Floor - 1, Cell))
110					{
111						return false;
112					}
113				}
114			}
115			return true;
116		}
