120		 * 유효하다 — 입구 문이 바로 그 경우다.
121		 */
122		void SetEdge(FCL9SiteLayout& Layout, int32 Floor, FIntPoint Cell, int32 Side, ECL9GridEdge State)
123		{
124			const uint8 Value = static_cast<uint8>(State);
125			const int32 BaseX = Floor * Layout.EdgeXStride();
126			const int32 BaseY = Floor * Layout.EdgeYStride();
127			switch (Side)
128			{
129			case SideE: Layout.EdgeX[BaseX + (Cell.X + 1) + Cell.Y * (Layout.GridSize.X + 1)] = Value; break;
130			case SideW: Layout.EdgeX[BaseX + Cell.X + Cell.Y * (Layout.GridSize.X + 1)] = Value; break;
131			case SideN: Layout.EdgeY[BaseY + Cell.X + (Cell.Y + 1) * Layout.GridSize.X] = Value; break;
132			default: Layout.EdgeY[BaseY + Cell.X + Cell.Y * Layout.GridSize.X] = Value; break;
133			}
134		}
