136		ECL9GridEdge GetEdge(const FCL9SiteLayout& Layout, int32 Floor, FIntPoint Cell, int32 Side)
137		{
138			switch (Side)
139			{
140			case SideE: return Layout.EdgeAtX(Floor, Cell.X + 1, Cell.Y);
141			case SideW: return Layout.EdgeAtX(Floor, Cell.X, Cell.Y);
142			case SideN: return Layout.EdgeAtY(Floor, Cell.X, Cell.Y + 1);
143			default: return Layout.EdgeAtY(Floor, Cell.X, Cell.Y);
144			}
145		}
