148		int32 Occupy(FCL9SiteLayout& Layout, const FCandidate& Cand, int32 Hops, int32 Floor, bool bStairUp)
149		{
150			FCL9ModulePlacement Placement;
151			Placement.Def = Cand.Def;
152			Placement.Origin = Cand.Origin;
153			Placement.Size = Cand.Size;
154			Placement.Rotation = Cand.Rotation;
155			Placement.Sockets = Cand.Sockets;
156			Placement.Hops = Hops;
157			Placement.Floor = Floor;
158			Placement.bStairUp = bStairUp;
159			const int32 Index = Layout.Modules.Add(Placement);
160	
161			for (int32 Level = Floor; Level <= Placement.TopFloor(); ++Level)
162			{
163				const int32 Base = Level * Layout.CellStride();
164				for (int32 Y = 0; Y < Cand.Size.Y; ++Y)
165				{
166					for (int32 X = 0; X < Cand.Size.X; ++X)
167					{
168						Layout.CellModule[Base + (Cand.Origin.X + X) + (Cand.Origin.Y + Y) * Layout.GridSize.X] = Index;
169					}
170				}
171			}
172			return Index;
173		}
