175		/** 모듈의 열린 변에 닿은 경계 칸들을 (칸, 바깥 방향)으로 훑는다 */
176		template <typename FuncType>
177		void ForEachBoundaryCell(const FCL9ModulePlacement& Module, FuncType&& Func)
178		{
179			for (int32 Side = 0; Side < 4; ++Side)
180			{
181				if (!HasSide(Module.Sockets, Side))
182				{
183					continue;
184				}
185				const int32 Count = (Side == SideN || Side == SideS) ? Module.Size.X : Module.Size.Y;
186				for (int32 Index = 0; Index < Count; ++Index)
187				{
188					FIntPoint Cell;
189					switch (Side)
190					{
191					case SideN: Cell = FIntPoint(Module.Origin.X + Index, Module.Origin.Y + Module.Size.Y - 1); break;
192					case SideS: Cell = FIntPoint(Module.Origin.X + Index, Module.Origin.Y); break;
193					case SideE: Cell = FIntPoint(Module.Origin.X + Module.Size.X - 1, Module.Origin.Y + Index); break;
194					default: Cell = FIntPoint(Module.Origin.X, Module.Origin.Y + Index); break;
195					}
196					Func(Cell, Side);
197				}
198			}
199		}
