201		/**
202		 * 프론티어 자리 하나에 앉힐 수 있는 배치를 전부 모은다. 회전 넷을 모두 시도하고,
203		 * 맞물릴 변을 따라 모듈을 미끄러뜨려 본다 — 3칸짜리 변이면 세 가지로 붙을 수 있다.
204		 */
205		void GatherCandidates(const FCL9SiteLayout& Layout, int32 Floor, const TArray<const UCL9ModuleDef*>& Pool,
206			FIntPoint Target, int32 Side, bool bNeedUpper, TArray<FCandidate>& Out)
207		{
208			Out.Reset();
209			const int32 Back = Opposite(Side);
210			for (const UCL9ModuleDef* Def : Pool)
211			{
212				for (int32 Rotation = 0; Rotation < 4; ++Rotation)
213				{
214					const uint8 Sockets = UCL9ModuleDef::RotateSockets(static_cast<uint8>(Def->Sockets & 0xF), Rotation);
215					if (!HasSide(Sockets, Back))
216					{
217						continue;
218					}
219					const FIntPoint Size = UCL9ModuleDef::RotateSize(Def->Size, Rotation);
220					const int32 Slide = (Back == SideN || Back == SideS) ? Size.X : Size.Y;
221					for (int32 Offset = 0; Offset < Slide; ++Offset)
222					{
223						FIntPoint Origin;
224						switch (Back)
225						{
226						case SideW: Origin = FIntPoint(Target.X, Target.Y - Offset); break;
227						case SideE: Origin = FIntPoint(Target.X - Size.X + 1, Target.Y - Offset); break;
228						case SideS: Origin = FIntPoint(Target.X - Offset, Target.Y); break;
229						default: Origin = FIntPoint(Target.X - Offset, Target.Y - Size.Y + 1); break;
230						}
231						if (!Fits(Layout, Floor, Origin, Size, bNeedUpper))
232						{
233							continue;
234						}
235	
236						FCandidate Cand;
237						Cand.Def = Def;
238						Cand.Origin = Origin;
239						Cand.Size = Size;
240						Cand.Rotation = Rotation;
241						Cand.Sockets = Sockets;
242						if (!Out.ContainsByPredicate([&Cand](const FCandidate& Other) { return Cand.SameOutcome(Other); }))
243						{
244							Out.Add(Cand);
245						}
246					}
247				}
248			}
249		}
