251		/** Rarity를 가중치로 하나 고른다 */
252		const FCandidate* PickCandidate(const TArray<FCandidate>& Candidates, FRandomStream& Rng)
253		{
254			int32 Total = 0;
255			for (const FCandidate& Cand : Candidates)
256			{
257				Total += FMath::Clamp(Cand.Def->Rarity, 1, 3);
258			}
259			if (Total <= 0)
260			{
261				return nullptr;
262			}
263			int32 Roll = Rng.RandRange(0, Total - 1);
264			for (const FCandidate& Cand : Candidates)
265			{
266				Roll -= FMath::Clamp(Cand.Def->Rarity, 1, 3);
267				if (Roll < 0)
268				{
269					return &Cand;
270				}
271			}
272			return &Candidates.Last();
273		}
