275		/**
276		 * 새로 놓인 모듈의 열린 경계 칸들을 한 층에서 훑어서, 빈 쪽은 그 층의 프론티어에
277		 * 넣고 이미 모듈이 있는 쪽은 확률로 문을 뚫는다(고리).
278		 *
279		 * **높이가 다른 두 방은 애초에 후보가 아니다** — 이 함수는 한 층 안에서만 도니까,
280		 * 리썰컴퍼니가 문틀을 3D 격자에 해시해서 얻는 성질이 여기서는 공짜로 성립한다.
281		 */
282		void OpenNeighbours(FCL9SiteLayout& Layout, int32 Floor, int32 ModuleIndex,
283			TArray<FFrontier>& Frontier, float LoopChance, FRandomStream& Rng)
284		{
285			const FCL9ModulePlacement Module = Layout.Modules[ModuleIndex];
286			ForEachBoundaryCell(Module, [&](FIntPoint Cell, int32 Side)
287			{
288				const FIntPoint Neighbour = Cell + SideDir[Side];
289				if (!Layout.IsInside(Neighbour))
290				{
291					return;
292				}
293				const int32 Other = Layout.CellAt(Floor, Neighbour);
294				if (Other == INDEX_NONE)
295				{
296					Frontier.Add({ModuleIndex, Cell, Side, Module.Hops});
297					return;
298				}
299				if (Other == ModuleIndex || GetEdge(Layout, Floor, Cell, Side) != ECL9GridEdge::Open)
300				{
301					return;
302				}
303				// 이웃도 이쪽 변이 열려 있어야 문이 된다. 이웃의 그 칸은 반드시 이웃의
304				// 경계 칸이다 — 우리 쪽 칸이 그 모듈 밖에 있으니까.
305				if (HasSide(Layout.Modules[Other].Sockets, Opposite(Side)) && Rng.FRand() < LoopChance)
306				{
307					SetEdge(Layout, Floor, Cell, Side, ECL9GridEdge::Door);
308				}
309			});
310		}
