178	ACL9SiteMap* ACL9SiteMap::Rebuild(UWorld* World, const UCL9SiteDef& Site, const UCL9DefRegistry& Registry, uint32 Seed, int32 Day)
179	{
180		if (World == nullptr)
181		{
182			return nullptr;
183		}
184	
185		ACL9SiteMap* Map = Find(World);
186		if (Map == nullptr)
187		{
188			// 트럭 패드가 사이트의 기준점이다. 맨 레벨에서는 PlayerStart가 그 자리를 대신한다
189			FVector Anchor = FVector::ZeroVector;
190			bool bFound = false;
191			for (TActorIterator<ACL9TruckPad> It(World); It; ++It)
192			{
193				Anchor = It->GetActorLocation();
194				bFound = true;
195				break;
196			}
197			if (!bFound)
198			{
199				for (TActorIterator<APlayerStart> It(World); It; ++It)
200				{
201					Anchor = It->GetActorLocation();
202					break;
203				}
204			}
205			Anchor.Z = 0.f;
206	
207			FActorSpawnParameters SpawnParams;
208			SpawnParams.ObjectFlags |= RF_Transient;
209			SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
210			Map = World->SpawnActor<ACL9SiteMap>(Anchor, FRotator::ZeroRotator, SpawnParams);
211			if (Map == nullptr)
212			{
213				UE_LOG(LogCL9, Error, TEXT("Site map: spawn failed."));
214				return nullptr;
215			}
216			Map->bIsEditorOnlyActor = World->WorldType == EWorldType::Editor;
217		}
218	
219		Map->Build(Site, Registry, Seed, Day);
220		return Map;
221	}
