286	void ACL9SiteMap::TickFlicker()
287	{
288		if (!bLampsOn || FlickerLamps.Num() == 0 || GetWorld() == nullptr)
289		{
290			return;
291		}
292		// 펄린 노이즈 한 줄 — 램프마다 위상이 달라 같은 박자로 깜박이지 않는다. 진폭 1이면 0~2배 사이.
293		const float Time = GetWorld()->GetTimeSeconds();
294		for (const FFlickerLamp& Entry : FlickerLamps)
295		{
296			UPointLightComponent* Lamp = LampComponents.IsValidIndex(Entry.LampIndex) ? LampComponents[Entry.LampIndex].Get() : nullptr;
297			if (Lamp != nullptr)
298			{
299				const float Noise = FMath::PerlinNoise1D(Time * Entry.Speed + Entry.Phase);
300				Lamp->SetIntensity(Entry.BaseIntensity * (1.f + Entry.Amplitude * Noise));
301			}
302		}
303	}
