305	void ACL9SiteMap::SetLampsOn(bool bOn)
306	{
307		if (bOn == bLampsOn)
308		{
309			return;
310		}
311		bLampsOn = bOn;
312		for (UPointLightComponent* Lamp : LampComponents)
