1201	void CL9SiteLayout::PointsInDepthBand(const FCL9SiteLayout& Layout, ECL9PointPurpose Purpose, float DepthMin, float DepthMax, TArray<int32>& OutIndices)
1202	{
1203		PointsOfPurpose(Layout, Purpose, OutIndices);
1204	
1205		// 깊이의 분모는 용도와 무관하게 판 전체에서 가장 먼 홉이다 — 그래야 용도가 다른 띠끼리 같은 눈금을 쓴다
1206		int32 MaxHops = 0;
1207		for (const FCL9LevelPoint& Point : Layout.Points)
1208		{
1209			MaxHops = FMath::Max(MaxHops, Point.Hops);
1210		}
1211		const float Scale = MaxHops > 0 ? 1.f / MaxHops : 0.f;
1212		OutIndices.RemoveAll([&](int32 Index)
1213		{
1214			const float Depth = Layout.Points[Index].Hops * Scale;
1215			// 끝은 제외하되, 1로 끝나는 띠는 가장 깊은 지점까지 품는다 — 띠를 이어 붙이면 빠지는 지점이 없다
1216			return Depth < DepthMin || (DepthMax >= 1.f ? Depth > 1.f : Depth >= DepthMax);
1217		});
1218	}
