1220	bool CL9SiteLayout::IsConnected(const FCL9SiteLayout& Layout)
1221	{
1222		if (Layout.Modules.Num() == 0)
1223		{
1224			return true;
1225		}
1226	
1227		TArray<uint8> Seen;
1228		Seen.Init(0, Layout.Modules.Num());
1229		TArray<int32> Queue;
1230		Queue.Add(0);
1231		Seen[0] = 1;
1232		int32 Reached = 0;
1233	
1234		while (Queue.Num() > 0)
1235		{
1236			const int32 Index = Queue.Pop(EAllowShrinking::No);
1237			++Reached;
1238			const FCL9ModulePlacement Module = Layout.Modules[Index];
1239			// 계단 모듈은 두 층에 걸쳐 있다 — 두 층의 문을 모두 훑어야 위층이 이어진다.
1240			for (int32 Floor = Module.Floor; Floor <= Module.TopFloor(); ++Floor)
1241			{
1242				if (!Layout.IsFloor(Floor))
1243				{
1244					continue;
1245				}
1246				ForEachBoundaryCell(Module, [&](FIntPoint Cell, int32 Side)
1247				{
1248					if (GetEdge(Layout, Floor, Cell, Side) != ECL9GridEdge::Door)
1249					{
1250						return;
1251					}
1252					const int32 Other = Layout.CellAt(Floor, Cell + SideDir[Side]);
1253					if (Other != INDEX_NONE && !Seen[Other])
1254					{
1255						Seen[Other] = 1;
1256						Queue.Add(Other);
1257					}
1258				});
1259			}
1260		}
1261		return Reached == Layout.Modules.Num();
1262	}
