1264	uint32 CL9SiteLayout::LayoutHash(const FCL9SiteLayout& Layout)
1265	{
1266		uint32 Hash = 2166136261u;
1267		FnvMix(Hash, Layout.Seed);
1268		FnvMix(Hash, static_cast<uint32>(Layout.GridSize.X));
1269		FnvMix(Hash, static_cast<uint32>(Layout.GridSize.Y));
1270		FnvMix(Hash, static_cast<uint32>(Layout.FloorCount));
1271		for (const FCL9ModulePlacement& Module : Layout.Modules)
1272		{
1273			FnvMix(Hash, GetTypeHash(Module.Def ? Module.Def->Alias : NAME_None));
1274			FnvMix(Hash, static_cast<uint32>(Module.Origin.X));
1275			FnvMix(Hash, static_cast<uint32>(Module.Origin.Y));
1276			FnvMix(Hash, static_cast<uint32>(Module.Rotation));
1277			FnvMix(Hash, static_cast<uint32>(Module.Floor));
1278		}
1279		for (uint8 Edge : Layout.EdgeX) FnvMix(Hash, Edge);
1280		for (uint8 Edge : Layout.EdgeY) FnvMix(Hash, Edge);
1281		return Hash;

